// ARC shared frame. The dispatch holds identifiers only (ADR ARC-010 §18); the webhook has
// already verified ARC's token. Ask ARC for the envelope: it re-checks everything first.
const request = $('ARC dispatch').first().json.body;
if (!request || request.contract_version !== 1) throw new Error('arc:validation_failed');
const now = Math.floor(Date.now() / 1000);
const envelopeRequest = {
  contract_version: 1,
  job_id: request.job_id,
  action_id: request.action_id,
  tenant_id: request.tenant_id,
  nonce: request.nonce,
};
return [{ json: {
  body: JSON.stringify(envelopeRequest),
  claims: { aud: 'arc-runner-bridge', purpose: 'envelope', iat: now, exp: now + 120, jti: `arc-n8n-${$execution.id}-envelope` },
} }];

// The module step. A real shared workflow does its module's work here, through ARC's
// connector gateway, never with a credential of its own. This reference workflow acts on
// nothing outside the execution: it exists to prove the frame around it.
const SUPPORTED = ['send_message'];
const answer = $('Send envelope request').first().json;
if (!answer || answer.contract_version !== 1 || !answer.envelope) throw new Error('arc:validation_failed');
const envelope = answer.envelope;
if (!SUPPORTED.includes(envelope.action_type)) throw new Error('arc:unsupported_capability');
// how the reference step behaves is the action's own payload, set by a test: never a tenant's settings.
const outcome = String(envelope.payload?.reference_outcome ?? 'succeed');
if (outcome.startsWith('fail:')) throw new Error(`arc:${outcome.slice(5)}`);
if (outcome === 'crash') throw new Error('the reference step crashed');
const status = outcome === 'skip' ? 'skipped' : 'succeeded';
return [{ json: {
  envelope,
  status,
  provider_refs: status === 'succeeded' ? [`reference:${envelope.job_id}`] : [],
  safe_output_meta: { reference: true },
} }];

// ARC shared frame. The outcome, proposed to ARC (ADR ARC-010 §19): ARC validates it and decides.
const WORKFLOW = { runner_key: 'arc-reference-action', workflow_version: '1.0.0' };
const done = $('Perform action').first().json;
const e = done.envelope;
const now = Math.floor(Date.now() / 1000);
const callback = {
  contract_version: 1,
  job_id: e.job_id,
  action_id: e.action_id,
  tenant_id: e.tenant_id,
  arc_attempt: e.attempt,
  n8n_execution_id: String($execution.id),
  runner_key: WORKFLOW.runner_key,
  workflow_version: WORKFLOW.workflow_version,
  status: done.status,
  provider_refs: done.provider_refs,
  safe_output_meta: done.safe_output_meta,
  error_category: null,
  retryable: false,
  completed_at: new Date().toISOString(),
  correlation_id: e.correlation_id,
  idempotency_key: e.idempotency_key,
};
return [{ json: {
  body: JSON.stringify(callback),
  claims: { aud: 'arc-runner-bridge', purpose: 'callback', iat: now, exp: now + 120, jti: `arc-n8n-${$execution.id}-callback` },
} }];
